import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第二十九卦 坎 坎為水 坎上坎下","description":"周易 - 第二十九卦 坎 坎為水 坎上坎下","frontmatter":{"title":"第二十九卦 坎 坎為水 坎上坎下","description":"周易 - 第二十九卦 坎 坎為水 坎上坎下"},"headers":[],"relativePath":"classics/zhouyi/030.md","filePath":"classics/zhouyi/030.md"}'),l={name:"classics/zhouyi/030.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="坎" tabindex="-1">坎 <a class="header-anchor" href="#坎" aria-label="Permalink to “坎”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>習坎，有孚，維心亨，行有尚。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>習坎，重險也。水流而不盈，行險而不失其信。維心亨，乃以剛中也。行有尚，往有功也。天險不可升也，地險山川丘陵也，王公設險以守其國，坎之時用大矣哉！</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>水洊至，習坎；君子以常德行，習教事。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>習坎，入於坎窞，兇。象曰：習坎入坎，失道兇也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>坎有險，求小得。象曰：求小得，未出中也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>來之坎坎，險且枕，入於坎窞，勿用。象曰：來之坎坎，終無功也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>樽酒簋貳，用缶，納約自牖，終無咎。象曰：樽酒簋貳，剛柔際也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>坎不盈，只既平，無咎。象曰：坎不盈，中未大也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>用徽繹，置於叢棘，三歲不得，兇。象曰：上六失道，兇三歲也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
